      "chunk_id": "text_0",
      "quote": "Association between food insecurity and key metabolic risk factors for diet-sensitive non-communicable diseases in sub-Saharan Africa: a systematic review and meta-analysis",
      "reason": "The title explicitly labels the report as a \"systematic review\"."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Association between food insecurity and key metabolic risk factors for diet-sensitive non-communicable diseases in sub-Saharan Africa: a systematic review and meta-analysis",
      "reason": "The title provides key review information by specifying the exposure (food insecurity) and the population/context (sub-Saharan Africa; diet-sensitive NCDs)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Association between food insecurity and key metabolic risk factors for diet-sensitive non-communicable diseases in sub-Saharan Africa: a systematic review and meta-analysis",
      "reason": "The title provides supplementary information about the analysis approach by stating the study includes a \"meta-analysis\"."
    }
  ],
  "confidence": 74
