{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_4",
      "quote": "While there are progressively better estimates of the prevalence of metabolic risk factors and proximate drivers of this prevalence in high-income countries; reliable data on the trend and patterns of key metabolic risk factors among the food insecure population in resource-limited settings, such as sub-Saharan African countries still lag far ­ behind 55 .",
      "reason": "The evidence describes a gap/uncertainty in current knowledge (lack of reliable data in resource-limited settings), but it is not clearly framed as “current state of knowledge and important uncertainties” within the Introduction section."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "In previous studies, food insecurity has been hypothesised to promote the prevalence of metabolic risk factors on the causal pathway to diet-sensitive non-communicable diseases (NCDs). This systematic review and meta-analysis aimed to determine the associations between food insecurity and key metabolic risk factors on the causal pathway to diet-sensitive NCDs and estimate the prevalence of key metabolic risk factors among the food-insecure patients in sub-Saharan Africa.",
      "reason": "The evidence explains the purpose/need for the review by stating what it sought to determine (associations and prevalence) in order to address an existing knowledge question."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Since this was the first meta-analysis (quantitative synthesis) regarding the epidemiology of metabolic risks among the food insecure population in sub-Saharan Africa; we tried to compare our findings to other surveys and reviews conducted outside of the sub-Saharan Africa or countries under study.",
      "reason": "The evidence identifies that similar reviews exist (mentions “Previous systematic reviews and several cross-sectional studies”) and explicitly positions the current work as the first meta-analysis for the target setting, providing a rationale for conducting the current review."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No intervention mechanism is described or proposed in the retrieved evidence; the review concerns epidemiological associations and prevalence, not an intervention effect."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not involve a complex intervention or delivery context requiring a logic model."
    }
  ],
  "confidence": 58
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "In this review, we first sought to identify the specific spectrum of key metabolic risk factors associated with food insecurity, by systematically reviewing current peer-reviewed epidemiological studies conducted in subSaharan Africa, assessing the associations between food insecurity and key metabolic risk factors on the causal pathway to diet-sensitive non-communicable diseases (NCDs). Secondly, after identifying the spectrum of key metabolic risk factors associated with food insecurity, we sought to assess the prevalence of these metabolic risk factors among the food-insecure patients in sub-Saharan Africa. Lastly, to assess study methodological quality (or risk of bias) of all included studies, we used the adopted Mixed Methods Appraisal Tool (MMAT)-Version ­ 2018 21 , as it permits for appraising the quality of quantitative non-randomized ­ studies 22,23 .\n\nThe main research question: What are the associations between food insecurity and key metabolic risk factors for diet-sensitive NCDs in the sub-Saharan African population?",
      "reason": "The review objective(s)/question(s) are explicitly stated, including a clearly articulated main research question and additional aims, and they are framed using a PEO (Population, Exposure, Outcomes) approach."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": "text_2",
      "quote": "In this review, we first sought to identify the specific spectrum of key metabolic risk factors associated with food insecurity ... Secondly, ... we sought to assess the prevalence of these metabolic risk factors among the food-insecure patients in sub-Saharan Africa.",
      "reason": "The conditional requirement concerns planned comparisons for reviews of intervention effects (PICO). This review’s stated objectives are about associations and prevalence in observational studies, and no planned intervention comparisons are described in the retrieved evidence."
    }
  ],
  "confidence": 78
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "table_2",
      "quote": "Table\u202f2. Eligibility criteria according to the PEO-T nomenclature criteria.\n\n| Criteria     | Inclusions                                                                                                                                                                                                                                                                                                              | Exclusions                                                                                                                                 |\n|--------------|-------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------|--------------------------------------------------------------------------------------------------------------------------------------------|\n| Study design | Only original and quantitative study design that are peer-reviewed cross- sectional studies conducted in sub-Saharan Africa by trained personnel, in any publication language                                                                                                                                           | Qualitative study design, and systematic reviews, literature reviews, mini-reviews and cross-sectional studies conducted outside of Africa |\n| Population   | Studies conducted among sub-Saharan African populations Participants of any age group and sex that did not mix the age groups for analysis Any ethnicity, culture, or race                                                                                                                                              | Research studies conducted among people outside of sub-Saharan Africa Participants with coexisting medical conditions                      |\n| Exposure     | Studies reporting a measure of food insecurity or food insufficiency as an inde- pendent variable A measure of food insecurity beyond receiving government-sponsored nutri- tional benefits/ or living in an area designated as a food desert Food insecurity evaluated at the household level or individual level      | Research studies reporting on voluntary food restriction, as in cases of anorexia/ Nervosa                                                 |\n| Outcomes     | Studies reporting at least one of the key metabolic risk factors as a dependent variable Diagnosed with key metabolic risk factors per any of the international diagnostic criteria for MetS: NCEP-ATP III, IDF, or AHA/NHLBI criteria or any other measures in line with the World Health Organization criteria (1998) | Research studies reporting on the outcome as the result of infectious agents None validated outcome measures                               |\n| Time         | Complete peer-reviewed original research studies, published between January 2015 and June 2019                                                                                                                                                                                                                          | Studies published before January 2015                                                                                                      |",
      "reason": "Eligibility characteristics are specified for study design, population, exposure, outcomes, and setting (sub-Saharan Africa). However, follow-up requirements are not specified (the eligibility criteria focus on cross-sectional designs and do not describe any follow-up/time horizon for participants)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "No language restrictions were imposed to minimise the risk that eligible studies could be inadvertently excluded. However, the year of publication was limited to between January 2015 and October 2019 to ensure that the evidence of associations is demonstrably rooted in the most recent and up-to-date scientific literature.",
      "reason": "The review specifies report characteristics: no language restrictions and a bounded publication year range."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not describe whether exclusions are distinguished based on whether outcomes were not measured versus excluded because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "we recognised the need to stratify the evidence of associations as reported by the studies into three strata of associations: Adverse Association, Nonsignificant Association, and Inconclusive Association.\n\n[-] Adverse Association-Food insecurity was reported to be significantly associated with \u2265 one key metabolic risk factor (observed with relevant statistical tool); [+] Non-significant Association-There was no significant association found between food insecurity and reported key metabolic risk factors (observed with relevant statistical tool); and [~] Inconclusive Association-The association between food insecurity and reported metabolic risk outcomes were inconclusive because, although exposure to food insecurity showed a protective effect toward reported metabolic risk factors, it was not statistically significant (observed with relevant statistical tool).",
      "reason": "The review clearly defines the groups (three association strata) used in the narrative synthesis for the primary outcome."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "However, the year of publication was limited to between January 2015 and October 2019 to ensure that the evidence of associations is demonstrably rooted in the most recent and up-to-date scientific literature. This decision was chiefly because practitioners and decision-makers are somewhat interested and encouraged to make use of the most current evidence to inform policy \u00ad debates 26 .",
      "reason": "A rationale is provided for the notable restriction on publication year."
    }
  ],
  "confidence": 78
}

